application.css:
* { box-sizing: border-box; }

:root {
  color: #172033;
  background: #eef2f7;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body { margin: 0; }
.page-shell { width: min(100% - 2rem, 900px); margin: 0 auto; padding: 3rem 0; }
.page-header { margin-bottom: 1.5rem; }
.eyebrow { color: #3157a4; font-size: .8rem; font-weight: 800; letter-spacing: .12em; margin: 0 0 .35rem; text-transform: uppercase; }
h1, h2 { line-height: 1.2; margin-top: 0; }
h1 { font-size: clamp(2rem, 5vw, 3rem); margin-bottom: .65rem; }
h2 { font-size: 1.35rem; margin-bottom: 1.25rem; }
.intro { color: #4b5870; margin: 0; }
.panel { background: #fff; border: 1px solid #d8e0eb; border-radius: 12px; box-shadow: 0 8px 24px rgba(27, 43, 72, .07); margin-top: 1.25rem; padding: clamp(1.25rem, 4vw, 2rem); }
.form-grid { display: grid; gap: 1rem; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.field-wide { grid-column: 1 / -1; }
.field { display: flex; flex-direction: column; gap: .4rem; }
label { font-weight: 700; }
input, select { background: #fff; border: 1px solid #8d9bb2; border-radius: 6px; color: #172033; font: inherit; min-height: 2.75rem; padding: .55rem .7rem; width: 100%; }
input:focus, select:focus, button:focus { outline: 3px solid #f5b942; outline-offset: 2px; }
.primary-button, .cancel-button { border: 0; border-radius: 6px; cursor: pointer; font: inherit; font-weight: 750; padding: .7rem 1rem; }
.primary-button { background: #244b92; color: #fff; margin-top: 1.25rem; }
.primary-button:hover { background: #193b78; }
.cancel-button { background: #f8e4e4; color: #8d2222; }
.message { border-radius: 6px; margin: 1rem 0 0; padding: .7rem .85rem; }
.error { background: #fff0f0; color: #8d2222; }
.confirmation { background: #e8f6ed; color: #176437; }
.section-heading { align-items: center; display: flex; justify-content: space-between; }
.count { background: #e7edf8; border-radius: 999px; color: #244b92; font-weight: 750; padding: .2rem .65rem; }
.booking-list { display: grid; gap: .8rem; }
.empty-state { color: #59677d; margin: 0; }
.booking { align-items: center; border: 1px solid #d8e0eb; border-radius: 8px; display: flex; gap: 1rem; justify-content: space-between; padding: 1rem; }
.booking.cancelled { background: #f5f6f8; opacity: .75; }
.booking-details { min-width: 0; }
.booking-details h3 { font-size: 1rem; margin: 0 0 .3rem; overflow-wrap: anywhere; }
.booking-details p { color: #4b5870; margin: .2rem 0; }
.status { color: #8d2222; font-size: .85rem; font-weight: 800; }
@media (max-width: 600px) { .page-shell { padding: 2rem 0; } .form-grid { grid-template-columns: 1fr; } .field-wide { grid-column: auto; } .booking { align-items: flex-start; flex-direction: column; } }

